from typing import Tuple

def inv_stereo(t: float) -> Tuple[float, float]:
    d: float = 1.0 + t * t
    return (2.0 * t / d, (1.0 - t * t) / d)

for t in [-5.0, -1.0, -0.3, 0.0, 0.5, 1.0, 2.0, 17.0]:
    x, y = inv_stereo(t)
    print(f"t={t:6.2f} -> ({x:+.6f},{y:+.6f})  norm={x*x+y*y:.12f}")

