from typing import Tuple

def inv_stereo(t: float) -> Tuple[float, float]:
    d: float = 1.0 + t * t
    return (2.0 * t / d, (1.0 - t * t) / d)

def stereo_proj(x: float, y: float) -> float:
    return x / (1.0 + y)

def rg_step(p: Tuple[float, float], lam: float) -> Tuple[float, float]:
    return inv_stereo(lam * stereo_proj(p[0], p[1]))

t0, lam = 0.3, 1.7
p = inv_stereo(t0)
for n in range(7):
    direct = inv_stereo((lam ** n) * t0)
    err = abs(p[0]-direct[0]) + abs(p[1]-direct[1])
    print(f"n={n}: flow={p}  direct={direct}  err={err:.2e}")
    p = rg_step(p, lam)

from fractions import Fraction
from typing import Tuple

def euclid_triple(m: int, n: int) -> Tuple[int, int, int]:
    return (2*m*n, m*m - n*n, m*m + n*n)

def inv_stereo_exact(t: Fraction) -> Tuple[Fraction, Fraction]:
    d = 1 + t*t
    return (2*t/d, (1 - t*t)/d)

for (m, n) in [(2,1),(3,2),(4,1),(5,2),(4,3)]:
    a, b, c = euclid_triple(m, n)
    print((a,b,c), 'check', a*a+b*b-c*c, 'sigma=', inv_stereo_exact(Fraction(n,m)))

