from typing import List, Tuple

def rg_orbit(t: float, lam: float, N: int) -> List[Tuple[float, float]]:
    """RG orbit on S^1: (RG_lam)^n(sigma(t)) = sigma(lam^n * t)."""
    orbit: List[Tuple[float, float]] = []
    for n in range(N + 1):
        s: float = (lam ** n) * t
        d: float = 1.0 + s * s
        orbit.append((2.0 * s / d, (1.0 - s * s) / d))
    return orbit

if __name__ == "__main__":
    for p in rg_orbit(0.3, 1.7, 6):
        print(f"({p[0]:+.6f}, {p[1]:+.6f})  norm={p[0]**2 + p[1]**2:.10f}")

from math import gcd
from typing import List, Tuple

def pythagorean_triples(limit: int) -> List[Tuple[int, int, int]]:
    """Primitive Pythagorean triples from sigma(n/m), m up to `limit`."""
    out: List[Tuple[int, int, int]] = []
    for m in range(2, limit + 1):
        for n in range(1, m):
            if gcd(m, n) == 1 and (m - n) % 2 == 1:
                a, b, c = 2 * m * n, m * m - n * n, m * m + n * n
                out.append((min(a, b), max(a, b), c))
    return out

if __name__ == "__main__":
    for tr in pythagorean_triples(6):
        a, b, c = tr
        print(tr, "check:", a * a + b * b - c * c)

